"""
Row-wise softmax in CUDA for H100.
Optimized for memory bandwidth on nvidia_h100_sxm.
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <cmath>
#include <limits>

// Number of warps per block (matching Triton's num_warps=8)
#define NUM_WARPS 8
#define WARP_SIZE 32
#define BLOCK_THREADS (NUM_WARPS * WARP_SIZE)  // 256 threads

// Optimized warp reduction for max
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    }
    return val;
}

// Optimized warp reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
