}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__device__ float block_reduce_max(float val, float* shared) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warp_reduce_max(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : -INFINITY;
        val = warp_reduce_max(val);
        if (lane == 0) shared[0] = val;
    }
    __syncthreads();

    return shared[0];
}

__device__ float block_reduce_sum(float val, float* shared) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warp_reduce_sum(val);
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : 0.0f;
        val = warp_reduce_sum(val);
        if (lane == 0) shared[0] = val;
    }
    __syncthreads();

    return shared[0];
}

// Use __ldg for read-only cache (texture cache on H100)
__device__ __forceinline__ half ldg_half(const half* ptr) {
    return __ldg(ptr);
}

__global__ void softmax_kernel(
    half* __restrict__ output,
    const half* __restrict__ input,
    const int input_row_stride,
    const int output_row_stride,
    const int n_rows,
    const int n_cols
) {
    __shared__ float shared_red[NUM_WARPS];
    __shared__ float shared_row_max;
    __shared__ float shared_row_sum;

    const int row_start = blockIdx.x;
    const int row_step = gridDim.x;
    const int tid = threadIdx.x;

    for (int row_idx = row_start; row_idx < n_rows; row_idx += row_step) {
        const half* row_input = input + row_idx * input_row_stride;
        half* row_output = output + row_idx * output_row_stride;

        // Phase 1: Find max with read-only cache
        float local_max = -INFINITY;

        // Unroll by 4 for better ILP
        int col = tid;
        for (; col + 3 * BLOCK_THREADS < n_cols; col += 4 * BLOCK_THREADS) {
            float v0 = __half2float(ldg_half(row_input + col));
            float v1 = __half2float(ldg_half(row_input + col + BLOCK_THREADS));
            float v2 = __half2float(ldg_half(row_input + col + 2 * BLOCK_THREADS));
            float v3 = __half2float(ldg_half(row_input + col + 3 * BLOCK_THREADS));
            local_max = fmaxf(local_max, fmaxf(fmaxf(v0, v1), fmaxf(v2, v3)));
        }
        for (; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(ldg_half(row_input + col));
            local_max = fmaxf(local_max, val);
        }

        float row_max = block_reduce_max(local_max, shared_red);

        if (tid == 0) shared_row_max = row_max;
        __syncthreads();
        row_max = shared_row_max;

        // Phase 2: Compute exp and sum
        float local_sum = 0.0f;

        col = tid;
        for (; col + 3 * BLOCK_THREADS < n_cols; col += 4 * BLOCK_THREADS) {
            float v0 = __half2float(ldg_half(row_input + col));
            float v1 = __half2float(ldg_half(row_input + col + BLOCK_THREADS));
            float v2 = __half2float(ldg_half(row_input + col + 2 * BLOCK_THREADS));
            float v3 = __half2float(ldg_half(row_input + col + 3 * BLOCK_THREADS));
            local_sum += expf(v0 - row_max) + expf(v1 - row_max) + 
                         expf(v2 - row_max) + expf(v3 - row_max);
        }
        for (; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(ldg_half(row_input + col));
            local_sum += expf(val - row_max);
        }

        float row_sum = block_reduce_sum(local_sum, shared_red);

        if (tid == 0) shared_row_sum = row_sum;
        __syncthreads();
        row_sum = shared_row_sum;

        // Phase 3: Write output
        float inv_sum = 1.0f / row_sum;

        col = tid;
        for (; col + 3 * BLOCK_THREADS < n_cols; col += 4 * BLOCK_THREADS) {
            float v0 = __half2float(ldg_half(row_input + col));
            float v1 = __half2float(ldg_half(row_input + col + BLOCK_THREADS));
            float v2 = __half2float(ldg_half(row_input + col + 2 * BLOCK_THREADS));
            float v3 = __half2float(ldg_half(row_input + col + 3 * BLOCK_THREADS));
            row_output[col] = __float2half(expf(v0 - row_max) * inv_sum);
            row_output[col + BLOCK_THREADS] = __float2half(expf(v1 - row_max) * inv_sum);
            row_output[col + 2 * BLOCK_THREADS] = __float2half(expf(v2 - row_max) * inv_sum);
            row_output[col + 3 * BLOCK_THREADS] = __float2half(expf(v3 - row_max) * inv_sum);
        }
        for (; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(ldg_half(row_input + col));
            row_output[col] = __float2half(expf(val - row_max) * inv_sum);
        }
    }
}

void launch_softmax_kernel(
    half* output,
    const half* input,
    int input_row_stride,
    int output_row_stride,
    int n_rows,
    int n_cols,
    cudaStream_t stream
) {
    int num_blocks = std::min(n_rows, 1024);
    softmax_kernel<<<num_blocks, BLOCK_THREADS, 0, stream>>>(
        output, input, input_row_stride, output_row_stride, n_rows, n_cols
    );
}
'''

# C++ wrapper code
cpp_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>

void launch_softmax_kernel(
    half* output,
    const half* input,
    int input_row_stride,
    int output_row_stride,
    int n_rows,
    int n_cols,
    cudaStream_t stream
);

torch::Tensor softmax_cuda(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(input.scalar_type() == torch::kFloat16, "Input must be float16");

    auto output = torch::empty_like(input);
    int n_rows = input.size(0);
    int n_cols = input.size(1);

    launch_softmax_kernel(
        reinterpret_cast<half*>(output.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(input.data_ptr<at::Half>()),
        input.stride(0),
        output.stride(0),
        n_rows,
        n_cols,
        at::cuda::getCurrentCUDAStream()
    );

    return output;
}
'''

# Load the extension
softmax_extension = load_inline(
    name='softmax_cuda_ext_v14',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['softmax_cuda'],
    extra_cuda_cflags=['-O3', '-use_fast_math'],
    verbose=False
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.softmax_cuda = softmax_extension.softmax_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_contiguous():
            x = x.contiguous()
        if not x.is_cuda:
            x = x.cuda()
        input_half = x if x.dtype == torch.float16 else x.half()
        return self.softmax_cuda(input_half)
